'use client'
import { cn, getLinkComponent, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import styles from './breadcrumb.module.css'

export interface BreadcrumbItem {
  /**
   * Stable React key. Provide when `label`/`href` may repeat.
   *
   * A real breadcrumb repeats hrefs — "Overview" and "Projects" both pointing at `/` is the
   * normal shape of a console trail — and without an `id` the crumbs key on their index, so
   * reordering or truncating the trail re-keys every row after the change.
   * `SideNavItem`, `ShellHeaderNavLink`, `ShellHeaderNavMenuItem`, `HeaderLink`,
   * `CommandItem` and `SwitcherLink` all carry this field; `BreadcrumbItem` was missed by
   * both earlier sweeps (2026-08-14 report §9).
   */
  id?: string
  label: string
  href?: string
}

export interface BreadcrumbProps {
  items: BreadcrumbItem[]
  maxVisible?: number
  className?: string
  /**
   * Accessible label for the component.
   *
   * @defaultValue `Breadcrumb`
   * @see the component manifest
   */
  ariaLabel?: string
  /**
   * Alias of `ariaLabel` — same invisible accessible name, the other spelling. Not rendered.
   *
   * `ariaLabel` is the catalog convention and stays preferred, but `label` is the guess an
   * adopter makes when they have not read the convention, and an unaccepted guess costs a
   * compile cycle for nothing (2026-08-21 report item 1). Pass either.
   */
  label?: string
}

export function Breadcrumb({ items, maxVisible, className, ariaLabel, label }: BreadcrumbProps) {
  useSignals()
  const LinkComponent = getLinkComponent()
  const resolvedAriaLabel = ariaLabel ?? label ?? t(builtin.breadcrumb.nav)
  let visible = items
  const first = items[0]
  if (first !== undefined && maxVisible !== undefined && items.length > maxVisible) {
    visible = [first, { label: '…' }, ...items.slice(items.length - (maxVisible - 2))]
  }

  return (
    <nav aria-label={resolvedAriaLabel} className={cn(styles['breadcrumb'], className)}>
      <ol>
        {visible.map((item, index) => {
          const isLast = index === visible.length - 1
          return (
            <li key={item.id ?? `${index}-${item.label}`}>
              {isLast ? (
                <span aria-current="page">{item.label}</span>
              ) : item.href !== undefined ? (
                <LinkComponent href={item.href}>{item.label}</LinkComponent>
              ) : (
                <span>{item.label}</span>
              )}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

@layer cascivo.component {
  .breadcrumb {
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-normal);

    & ol {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: var(--cascivo-space-2);
      margin: 0;
      padding: 0;
      list-style: none;
    }

    & li {
      display: inline-flex;
      align-items: center;
      gap: var(--cascivo-space-2);
      color: var(--cascivo-color-text-muted);
    }

    /* Separator — alt text '' keeps it out of the accessibility tree */
    & li + li::before {
      content: '/' / '';
      color: var(--cascivo-color-text-subtle);
    }

    & a {
      color: var(--cascivo-color-text-muted);
      text-decoration: none;
      border-radius: var(--cascivo-radius-item);
      transition: color var(--cascivo-duration-150) var(--cascivo-ease-out);

      &:hover {
        color: var(--cascivo-color-text);
        text-decoration: underline;
      }

      &:focus-visible {
        outline: none;
        box-shadow: var(--cascivo-focus-ring);
      }
    }

    & [aria-current='page'] {
      color: var(--cascivo-color-text);
      font-weight: var(--cascivo-font-medium);
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Breadcrumb',
  description: 'Shows the current page location within a navigation hierarchy',
  category: 'navigation',
  // Markup is fully server-rendered; the only client-side work is re-resolving the
  // default label when the i18n locale or catalog changes, which is why the source
  // calls useSignals() and carries 'use client'. Nothing is unreachable with JS off.
  clientJs: 'enhancement',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'items',
      description: 'The items to render.',
      type: '{ label: string; href?: string }[]',
      required: true,
    },
    {
      name: 'maxVisible',
      type: 'number',
      required: false,
      description:
        'When items exceed this count, collapse to the first item, an ellipsis, and the trailing items',
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
    {
      name: 'label',
      nameVisibility: 'invisible',
      description:
        'Alias of `ariaLabel` — the same invisible accessible name under the other spelling. Neither is deprecated.',
      type: 'string',
      required: false,
    },
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      description: 'Accessible label for the component.',
      type: 'string',
      required: false,
      default: 'Breadcrumb',
    },
  ],
  tokens: [
    '--cascivo-color-text',
    '--cascivo-color-text-muted',
    '--cascivo-color-text-subtle',
    '--cascivo-radius-sm',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'navigation',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Enter'],
  },
  examples: [
    {
      title: 'Basic',
      code: "<Breadcrumb items={[{ label: 'Home', href: '/' }, { label: 'Docs', href: '/docs' }, { label: 'Breadcrumb' }]} />",
    },
    {
      title: 'Collapsed',
      code: "<Breadcrumb maxVisible={3} items={[{ label: 'Home', href: '/' }, { label: 'Docs', href: '/docs' }, { label: 'Components', href: '/docs/components' }, { label: 'Breadcrumb' }]} />",
      description: 'Long trails collapse to the first item, an ellipsis, and the trailing items.',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['breadcrumb', 'navigation', 'hierarchy'],
  intent: {
    whenToUse: [
      'Showing the user where the current page sits in a navigation hierarchy',
      'Providing one-click navigation back to ancestor pages',
      'Collapsing deep trails to keep the trail compact (maxVisible)',
    ],
    whenNotToUse: [
      'Paging through data records — use Pagination',
      'Switching between sibling views — use Tabs',
    ],
    antiPatterns: [
      {
        bad: 'Using Breadcrumb to step through pages 1, 2, 3 of a dataset',
        good: '<Pagination> for paged data',
        why: 'Breadcrumb models hierarchy depth, not sequential position in a list',
      },
    ],
    related: [
      {
        name: 'Pagination',
        relationship: 'alternative',
        reason: 'Pagination moves through data pages; Breadcrumb moves up a hierarchy',
      },
    ],
    a11yRationale:
      'Wrapped in <nav> with an aria-label and the current page marked aria-current="page"; ancestor entries are real links so keyboard users can jump up the hierarchy',
    content: {
      tone: 'Short labels matching page titles',
      notes: 'The last item is the current page and is not a link',
    },
    flexibility: [
      {
        area: 'maxVisible',
        level: 'flexible',
        note: 'Collapse long trails to fit available width',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Text colors and focus ring must resolve to --cascivo-* tokens',
      },
    ],
  },
}
